package cli

import (
	"errors"
	"fmt"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/api"
)

func TestShowMessages(t *testing.T) {
	_, err := planTrailBranchChange(t.Context(), &api.TrailResource{Number: 575, Branch: "old-branch"}, trailUpdateInputs{SetBranch: "feature/x", SetBranchChanged: true})
	fmt.Println("MOVE:", err)
	fmt.Println("HAS: ", explainTrailBranchConflict(fmt.Errorf("trail API: %w", errors.New("Trail already has a linked branch")), 575, "feature/x"))
	fmt.Println("DUP: ", explainTrailBranchConflict(fmt.Errorf("trail API: %w", errors.New("This branch is already linked to another trail")), 575, "feature/x"))
}
